// Arrange-Act-Assert pattern
describe('calculateDiscount', () => {
  it('applies 10% discount to positive price', () => {
    // Arrange
    const price = 100;
    const discountRate = 0.10;

    // Act
    const result = calculateDiscount(price, discountRate);

    // Assert
    expect(result).toBe(90);
  });

  it('returns original price when discount rate is 0', () => {
    expect(calculateDiscount(50, 0)).toBe(50);
  });

  it('throws when price is negative', () => {
    expect(() => calculateDiscount(-10, 0.1)).toThrow('Price must be positive');
  });
});

