// Function under test: accepts age 18–65
function isEligible(age: number): boolean {
  return age >= 18 && age <= 65;
}

// Boundary test cases
describe('isEligible — boundary values', () => {
  it.each([
    [17, false],  // just below min
    [18, true],   // min boundary
    [19, true],   // just above min
    [64, true],   // just below max
    [65, true],   // max boundary
    [66, false],  // just above max
  ])('age %i → %s', (age, expected) => {
    expect(isEligible(age)).toBe(expected);
  });
});

// k6 load test — verifies p99 latency SLO
import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
  stages: [
    { duration: '2m', target: 100 },  // ramp up
    { duration: '5m', target: 500 },  // sustained load
    { duration: '2m', target: 0   },  // ramp down
  ],
  thresholds: {
    http_req_duration: ['p(99)<400'],  // 99th percentile < 400ms
    http_req_failed:   ['rate<0.001'], // error rate < 0.1%
  },
};

export default function () {
  const res = http.get('https://staging.example.com/api/search?q=widget');
  check(res, { 'status is 200': (r) => r.status === 200 });
  sleep(1);
}

